import { getEmployee } from "@/config/employees";

const TELNYX_API_KEY = process.env.TELNYX_API_KEY;

export async function generateToken(employeeId: string) {
  const employee = getEmployee(employeeId);
  if (!employee) throw new Error("Employee not found");

  const response = await fetch(
    `https://api.telnyx.com/v2/telephony_credentials`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${TELNYX_API_KEY}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        connection_id: employee.connectionId,
        name: `token-${employee.id}-${Date.now()}`,
      }),
    }
  );

  if (!response.ok) {
    const err = await response.text();
    throw new Error(`Telnyx API error: ${response.status} ${err}`);
  }

  const data = await response.json();
  const credentialId = data.data.id;

  // Generate JWT token from the credential
  const tokenResponse = await fetch(
    `https://api.telnyx.com/v2/telephony_credentials/${credentialId}/token`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${TELNYX_API_KEY}`,
        "Content-Type": "application/json",
      },
    }
  );

  if (!tokenResponse.ok) {
    const err = await tokenResponse.text();
    throw new Error(`Telnyx token error: ${tokenResponse.status} ${err}`);
  }

  const tokenText = await tokenResponse.text();
  return {
    token: tokenText,
    callerNumber: employee.callerNumber,
    employeeName: employee.name,
  };
}

